import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import { test } from 'node:test';
import { fileURLToPath } from 'node:url';

import { TOPICS, topicSlugs } from '../../src/topics.mjs';

const DOCS = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../../src/content/docs');
// Generated by scripts/sync-docs.mjs from the repository's own documents (reached via autogenerate),
// and reference/otlp-compatibility.mdx by backend/scripts/gen_otlp_matrix.py from the OTLP fixtures.
const GENERATED = ['api', 'runbooks', 'security', 'deploy', 'changelog.md', 'reference/prices.md', 'reference/otlp-compatibility.mdx'];

function handWrittenSlugs() {
  const slugs = [];
  const walk = (dir, prefix) => {
    for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
      const rel = prefix ? `${prefix}/${entry.name}` : entry.name;
      if (GENERATED.includes(rel)) continue;
      if (entry.isDirectory()) walk(path.join(dir, entry.name), rel);
      else if (/\.mdx?$/.test(entry.name) && rel !== 'index.mdx') slugs.push(rel.replace(/\.mdx?$/, ''));
    }
  };
  walk(DOCS, '');
  return slugs.sort();
}

test('every hand-written page belongs to exactly one topic', () => {
  const listed = topicSlugs(TOPICS);
  for (const slug of handWrittenSlugs()) {
    assert.equal(listed.filter((s) => s === slug).length, 1, `${slug} should appear in exactly one topic`);
  }
});

test("topics come in the spec's order", () => {
  assert.deepEqual(
    TOPICS.map((topic) => topic.label),
    ['Get started', 'Concepts', 'Guides', 'Integrations', 'Self-hosting', 'Reference'],
  );
});

/** The autogenerate directories a topic reaches, however deeply its groups nest. */
function autogenerateDirectories(items) {
  return items.flatMap((item) =>
    typeof item === 'string' ? [] : item.autogenerate ? [item.autogenerate.directory] : autogenerateDirectories(item.items ?? []),
  );
}

function pagesIn(dir) {
  const root = path.join(DOCS, dir);
  if (!fs.existsSync(root)) return [];
  return fs.readdirSync(root, { recursive: true }).filter((name) => /\.mdx?$/.test(String(name)));
}

test('no topic is empty', () => {
  for (const topic of TOPICS) {
    const named = topicSlugs([topic]).length;
    const generated = autogenerateDirectories(topic.items).reduce((count, dir) => count + pagesIn(dir).length, 0);
    assert.ok(named + generated > 0, `${topic.label} has no pages (no named page, and no page in an autogenerate group)`);
  }
});

test('every autogenerate group has pages', () => {
  for (const topic of TOPICS) {
    for (const dir of autogenerateDirectories(topic.items)) {
      assert.ok(pagesIn(dir).length > 0, `${topic.label} autogenerates ${dir}, which has no pages`);
    }
  }
});

test('the Integrations topic sits after Guides, with the puzzle icon, and lists its index', () => {
  const topic = TOPICS.find((candidate) => candidate.label === 'Integrations');
  assert.ok(topic, 'no Integrations topic');
  assert.equal(topic.link, '/integrations/');
  assert.equal(topic.icon, 'puzzle');
  assert.ok(topic.items.includes('integrations'));
});

test('integrations index links every page in the Integrations topic', () => {
  const topic = TOPICS.find((candidate) => candidate.label === 'Integrations');
  assert.ok(topic, 'no Integrations topic');
  const index = fs.readFileSync(path.join(DOCS, 'integrations.mdx'), 'utf8');
  const missing = topicSlugs([topic])
    .filter((slug) => slug !== 'integrations')
    .filter((slug) => !index.includes(`/docs/${slug}/`));
  assert.deepEqual(missing, [], `integrations.mdx does not link ${missing.join(', ')}`);
});

test('every topic link points at a page that exists', () => {
  for (const topic of TOPICS) {
    const slug = topic.link.replace(/^\/|\/$/g, '');
    const exists = ['.md', '.mdx'].some((ext) => fs.existsSync(path.join(DOCS, slug + ext)))
      || fs.existsSync(path.join(DOCS, slug, 'index.md'));
    assert.ok(exists, `${topic.label} links to missing page ${topic.link}`);
  }
});

test("every topic link's page belongs to that topic", () => {
  const directories = autogenerateDirectories;
  for (const topic of TOPICS) {
    const slug = topic.link.replace(/^\/|\/$/g, '');
    const listed = topicSlugs([topic]).includes(slug);
    const generated = directories(topic.items).some((dir) => slug === dir || slug.startsWith(`${dir}/`));
    assert.ok(listed || generated, `${topic.label} links to ${topic.link}, which is not one of its own pages`);
  }
});

test('split pages keep a pointer under each moved heading', () => {
  const pointer = (file, heading, target) => {
    const text = fs.readFileSync(path.join(DOCS, file), 'utf8');
    const at = text.indexOf(`\n${heading}\n`);
    assert.ok(at >= 0, `${file} lost the heading "${heading}"`);
    const section = text.slice(at + heading.length + 2).split(/\n## /)[0];
    assert.ok(section.includes(`](${target})`), `${file} "${heading}" should link to ${target}`);
  };
  pointer('doctor.mdx', '## The catalogue', '/docs/reference/detectors/');
  pointer('guides/data.mdx', '## Exports', '/docs/guides/exports/');
  pointer('otlp.mdx', '## How attributes map', '/docs/reference/otlp-mapping/');
  assert.ok(topicSlugs(TOPICS).includes('reference/detectors'));
  assert.ok(topicSlugs(TOPICS).includes('guides/exports'));
  assert.ok(topicSlugs(TOPICS).includes('reference/otlp-mapping'));
  assert.ok(topicSlugs(TOPICS).includes('reference/prices'));
});
